public static String reverse(String str) {
    if (str == null) {
        return null;
    }

    int length = str.length();
    int mid = length/2;
    for (int i=0; i<mid; i++) {
        char ch = str.charAt(i);
        str.setCharAt(i, str.charAt(length - 1 - i));
        str.setCharAt(length-1-i, ch);
    }
    return str;
}

