public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    Set<String> keys = resultMap.keySet();
    int numVertices = keys.size();
    if (numVertices == 0) {
        return;
    }
    Iterator<String> keyIter = keys.iterator();
    List<V> vertices = new ArrayList<>(numVertices);
    while (keyIter.hasNext()) {
        String key = keyIter.next();
        V vertex = resultMap.get(key);
        vertices.add(vertex);
    }
    target.addVertices(vertices);
    int numEdges = numVertices * (numVertices - 1) / 2;
    for (int i = 0; i < numEdges; i++) {
        V from = vertices.get(i);
        V to = vertices.get((i + numVertices - 1) % numVertices);
        target.addEdge(from, to);
    }
}

@Override
public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    // Create a new Graph instance if the target Graph is null
    if (target == null) {
        target = new Graph<>();
    }
    // Generate a complete bipartite graph with a random number of vertices from each side
    int numVertices1 = random.nextInt(50);
    int numVertices2 = random.nextInt(50);
    // Create the vertices for the first side of the graph
    for (int i = 0; i < numVertices1; i++) {
        target.addVertex(i);
    }
    // Create the vertices for the second side of the graph
    for (int i = 0; i < numVertices2; i++) {
        target.addVertex(i + numVertices1);
    }
    // Generate random edges between the vertices
    for (int i = 0; i < numVertices1; i++) {
        for (int j = 0; j < numVertices2; j++) {
            target.addEdge(i, i + numVertices1 + j, random.nextInt(15));
        }
    }
    // Add the vertices and edges to the result map
    for (int i = 0; i < numVertices1; i++) {
        resultMap.put(Integer.toString(i), target.get(i));
    }
    for (int i = 0; i < numVertices2; i++) {
        resultMap.put(Integer.toString(i + numVertices1), target.get(i + numVertices1));
    }
}

public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
        for (V vertex : resultMap.values()) {
            target.addVertex(vertex);
            for (E edge : resultMap.entrySet()) {
                target.addEdge(edge);
            }
        }
    }

@Override
public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    // For each vertex in the result map
    for (Map.Entry<String, V> entry : resultMap.entrySet()) {
        V vertex = entry.getValue();
        // Add the vertex to the graph
        target.addVertex(vertex);
        // Iterate over the adjacent vertices in the same set
        for (Map.Entry<String, V> adjacentEntry : resultMap.entrySet()) {
            V adjacentVertex = adjacentEntry.getValue();
            if (adjacentVertex.equals(vertex)) {
                continue;
            }
            // Add edge between the vertex and the adjacent vertex
            target.addEdge(vertex, adjacentVertex);
        }
    }
}

