        vertices.add(vertex);
    }
    target.addVertices(vertices);
    int numEdges = numVertices * (numVertices - 1) / 2;
    for (int i = 0; i < numEdges; i++) {
        V from = vertices.get(i);
        V to = vertices.get((i + numVertices - 1) % numVertices);
        target.addEdge(from, to);
    }
