public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    // Create a new Graph instance if the target Graph is null
    if (target == null) {
        target = new Graph<>();
    }
    // Generate a complete bipartite graph with a random number of vertices from each side
    int numVertices1 = random.nextInt(50);
    int numVertices2 = random.nextInt(50);
    // Create the vertices for the first side of the graph
    for (int i = 0; i < numVertices1; i++) {
        target.addVertex(i);
    }
    // Create the vertices for the second side of the graph
    for (int i = 0; i < numVertices2; i++) {
        target.addVertex(i + numVertices1);
    }
    // Generate random edges between the vertices
    for (int i = 0; i < numVertices1; i++) {
        for (int j = 0; j < numVertices2; j++) {
            target.addEdge(i, i + numVertices1 + j, random.nextInt(15));
        }
    }
    // Add the vertices and edges to the result map
    for (int i = 0; i < numVertices1; i++) {
        resultMap.put(Integer.toString(i), target.get(i));
    }
    for (int i = 0; i < numVertices2; i++) {
        resultMap.put(Integer.toString(i + numVertices1), target.get(i + numVertices1));
    }
}

