@Override
public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    // For each vertex in the result map
    for (Map.Entry<String, V> entry : resultMap.entrySet()) {
        V vertex = entry.getValue();
        // Add the vertex to the graph
        target.addVertex(vertex);
        // Iterate over the adjacent vertices in the same set
        for (Map.Entry<String, V> adjacentEntry : resultMap.entrySet()) {
            V adjacentVertex = adjacentEntry.getValue();
            if (adjacentVertex.equals(vertex)) {
                continue;
            }
            // Add edge between the vertex and the adjacent vertex
            target.addEdge(vertex, adjacentVertex);
        }
    }
}

