    if (bucket != null && i != minLabel) {
      for (int element : bucket) {
        labels.set(element, 0);
      }
      bucket.clear();
    }
  }
}

private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    // Find the minimum value of the non-empty bucket and clear it
    int minBucketIndex = labels.indexOf(minLabel);
    bucketsByLabel.get(minBucketIndex).clear();

    // Move all vertices from the bucket with minimum value to the bucket with label 0
    List<Integer> verticesToMove = new ArrayList<>();
    for (Integer vertex : bucketsByLabel.get(minBucketIndex)) {
        verticesToMove.add(vertex);
    }
    for (Integer vertex : verticesToMove) {
        bucketsByLabel.get(0).add(vertex);
    }

    // Update the labeling accordingly
    for (int i = minBucketIndex; i < bucketsByLabel.size() - 1; i++) {
        labels.set(i, labels.get(i + 1));
    }
    labels.set(labels.size() - 1, 0);
}

