public Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {

    // Initialize sum variable to be used in the function
    long tempSum = 0;
    List<Integer> suffixSumList = new ArrayList<>();

    // Calculate the sum of all elements in the list
    for (int i : bounds) {
        tempSum += i;
    }

    // Compute the suffix sum of the list
    for (int i = bounds.size() - 1; i >= 0; i--) {
        suffixSumList.add(tempSum - bounds.get(i));
    }

    // Return pair of suffix sum list and sum of all elements
    return new Pair<List<Integer>, Long>(suffixSumList, tempSum);
}

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {

    List<Integer> suffixSumList = new ArrayList<>();

    long sum = 0;

    for (int i = 0; i < bounds.size(); i++) {
        sum += bounds.get(i);
        suffixSumList.add(sum);
    }

    return new Pair<List<Integer>, Long>(suffixSumList, sum);
}

