public static Pair<List<Integer>,Long> computeSuffixSum(final List<Integer> bounds){

    if(bounds == null){
        throw new NullPointerException("The input list cannot be null.");
    }

    long sum = 0;
    final ArrayList<Integer> suffixSums = new ArrayList<>(bounds.size());

    for(int i = bounds.size() - 1; i >= 0; i--){
        sum += bounds.get(i);
        suffixSums.add(0, (int)sum);
    }

    return new Pair<>(suffixSums, sum);
