                }
                String hex = input.substring(i + 1, i + 5);
                try {
                    int unescapedChar = Integer.parseInt(hex, 16);
                    sb.append((char) unescapedChar);
                    i = i + 4;
                } catch (NumberFormatException e) {
                    break;
                }
            } else if (c == 'U') {
                if (i + 8 >= input.length()) {
                    break;
                }
                String hex = input.substring(i + 1, i + 9);
                try {
                    int unescapedChar = Integer.parseInt(hex, 16);
                    sb.append((char) unescapedChar);
                    i = i + 8;
                } catch (NumberFormatException e) {
                    break;
                }
            } else {
                sb.append('\\').append(c);
            }
        } else {
            sb.append(c);
        }
