    // Calculate the number of intervals to split the time range into
    int numIntervals = (int) Math.ceil((double) (end - start) / FETCH_DATA_DURATION);

    // Create a list to store the time ranges
    List<TimeRange> timeRanges = new ArrayList<>(numIntervals);

    // Add each time range to the list
    for (int i = 0; i < numIntervals; i++) {
        // Calculate the start and end time of each interval
        long intervalStart = start + i * FETCH_DATA_DURATION;
        long intervalEnd = Math.min(end, intervalStart + FETCH_DATA_DURATION);

        // Create a new time range object for each interval
        TimeRange timeRange = new TimeRange(intervalStart, intervalEnd);

        // Add the time range to the list
        timeRanges.add(timeRange);
    }

    return timeRanges;
}

